// src/core/profile/profile-physical.types.ts
// Tipos para perfil físico/interesses/personalidade

export interface InterestCategory {
  categoryId: string;
  categoryName: string;
  categoryPath: string[];
  level: number;
}

export interface LifestyleInfo {
  drinks: 'never' | 'socially' | 'regularly' | 'prefer_not_to_say' | null;
  smokes: 'never' | 'occasionally' | 'regularly' | 'prefer_not_to_say' | null;
  relationshipStatus: 'single' | 'dating' | 'in_relationship' | 'married' | 'prefer_not_to_say' | null;
  sexualOrientation: 'heterosexual' | 'homosexual' | 'bisexual' | 'pansexual' | 'asexual' | 'prefer_not_to_say' | null;
}

export interface PhysicalProfile {
  globalUserId: string;
  interests: InterestCategory[]; // Categorias de interesse selecionadas
  lifestyle: LifestyleInfo;
  preferences: {
    // Preferências específicas por categoria
    [categoryId: string]: {
      details?: string[]; // Ex: ["RPG", "Ação"] para jogos
      notes?: string; // Observações adicionais
    };
  };
  metadata: Record<string, any>; // Dados adicionais flexíveis
}

export interface UpdatePhysicalProfileInput {
  interests?: string[]; // Array de categoryIds
  lifestyle?: Partial<LifestyleInfo>;
  preferences?: {
    [categoryId: string]: {
      details?: string[];
      notes?: string;
    };
  };
  metadata?: Record<string, any>;
}











